'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var instanceOf = require( '@stdlib/assert/instance-of' );
var isBoolean = require( '@stdlib/assert/is-boolean' ).isPrimitive;
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isPlainObject = require( '@stdlib/assert/is-plain-object' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var Autosize = require( './../lib' );


// MAIN //

bench( format( '%s::instantiation', pkg ), function benchmark( b ) {
	var v;
	var i;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = new Autosize();
		if ( !instanceOf( v, Autosize ) ) {
			b.fail( 'should return an instance' );
		}
	}
	b.toc();
	if ( !instanceOf( v, Autosize ) ) {
		b.fail( 'should return an instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::instantiation,no_new', pkg ), function benchmark( b ) {
	var ctor;
	var v;
	var i;

	ctor = Autosize;

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = ctor();
		if ( !instanceOf( v, Autosize ) ) {
			b.fail( 'should return an instance' );
		}
	}
	b.toc();
	if ( !instanceOf( v, Autosize ) ) {
		b.fail( 'should return an instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::instantiation,options', pkg ), function benchmark( b ) {
	var opts;
	var v;
	var i;

	opts = {
		'contains': 'padding',
		'resize': true,
		'type': 'fit'
	};

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = new Autosize( opts );
		if ( !instanceOf( v, Autosize ) ) {
			b.fail( 'should return an instance' );
		}
	}
	b.toc();
	if ( !instanceOf( v, Autosize ) ) {
		b.fail( 'should return an instance' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::set,get:contains', pkg ), function benchmark( b ) {
	var values;
	var v;
	var i;

	values = [
		'content',
		'padding'
	];
	v = new Autosize();

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v.contains = values[ i % values.length ];
		if ( !isString( v.contains ) ) {
			b.fail( 'should return a string' );
		}
	}
	b.toc();
	if ( !isString( v.contains ) ) {
		b.fail( 'should return a string' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::set,get:resize', pkg ), function benchmark( b ) {
	var values;
	var v;
	var i;

	values = [
		true,
		false
	];
	v = new Autosize();

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v.resize = values[ i % values.length ];
		if ( !isBoolean( v.resize ) ) {
			b.fail( 'should return a boolean' );
		}
	}
	b.toc();
	if ( !isBoolean( v.resize ) ) {
		b.fail( 'should return a boolean' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s::set,get:type', pkg ), function benchmark( b ) {
	var values;
	var v;
	var i;

	values = [
		'pad',
		'fit',
		'none'
	];
	v = new Autosize();

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v.type = values[ i % values.length ];
		if ( !isString( v.type ) ) {
			b.fail( 'should return a string' );
		}
	}
	b.toc();
	if ( !isString( v.type ) ) {
		b.fail( 'should return a string' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});

bench( format( '%s:toJSON', pkg ), function benchmark( b ) {
	var values;
	var v;
	var o;
	var i;

	values = [
		'pad',
		'fit',
		'none'
	];
	v = new Autosize();

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v.type = values[ i % values.length ];
		o = v.toJSON();
		if ( typeof o !== 'object' ) {
			b.fail( 'should return an object' );
		}
	}
	b.toc();
	if ( !isPlainObject( o ) ) {
		b.fail( 'should return an object' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});
